UPDATE refund
SET total_refund_amount = #{totalRefundAmount}
WHERE refund_no = #{refundNo}

UPDATE order_item
SET refunded_quantity = refunded_quantity + #{refundQuantity}
WHERE order_item_no = #{orderItemNo}

UPDATE order_item
SET order_item_status = #{orderItemStatus}
WHERE order_item_no = #{orderItemNo}

UPDATE orders
SET order_status = #{orderStatus}
WHERE order_no = #{orderNo}
